"use client"

import { createContext, useContext, useState, useEffect, type ReactNode, useCallback } from "react"
import { useAuth } from "@/lib/store/auth-store"
import { useToast } from "@/hooks/use-toast"

// Función para obtener cliente PocketBase
const getPbClient = () => {
  if (typeof window === 'undefined') return null
  
  try {
    const PocketBase = require('pocketbase').default
    const POCKETBASE_URL = process.env.NEXT_PUBLIC_POCKETBASE_URL || 'http://127.0.0.1:8090'
    const pb = new PocketBase(POCKETBASE_URL)
    pb.autoCancellation(false)
    return pb
  } catch (error) {
    return null
  }
}

interface PointsContextType {
  points: number
  is_loading: boolean
  addPoints: (amount: number, description?: string) => Promise<void>
  usePoints: (amount: number, description?: string) => Promise<boolean>
  points_history: { amount: number; type: "earned" | "spent"; description: string; timestamp: string }[]
  refreshPoints: () => Promise<void>
  getCurrentUserPoints: () => Promise<number>
}

const PointsContext = createContext<PointsContextType | null>(null)

export function PointsProvider({ children }: { children: ReactNode }) {
  const { user } = useAuth()
  const { toast } = useToast()
  const [points, setPoints] = useState(250)
  const [is_loading, setIsLoading] = useState(true)
  const [points_history, setPointsHistory] = useState<
    { amount: number; type: "earned" | "spent"; description: string; timestamp: string }[]
  >([])

  // Cargar puntos del usuario
  const refreshPoints = useCallback(async () => {
    try {
      setIsLoading(true)
      
      if (!user?.id) {
        // Si no hay usuario, cargar del localStorage
        const savedPoints = localStorage.getItem("imperial_points")
        if (savedPoints) {
          setPoints(Number.parseInt(savedPoints, 10))
        }
        return
      }

      // Intentar con PocketBase
      const pb = getPbClient()
      if (pb) {
        try {
          const userRecord = await pb.collection('users').getOne(user.id)
          setPoints(userRecord.points || 250)

          // Obtener historial de puntos
          const history = await pb.collection('points_history').getFullList({
            filter: `user = "${user.id}"`,
            sort: '-created',
          })
          
          setPointsHistory(history.map(record => ({
            amount: record.amount,
            type: record.type,
            description: record.description || '',
            timestamp: record.created
          })))
          return
        } catch (error) {
          console.warn('No se pudo conectar a PocketBase, usando puntos locales:', error)
        }
      }

      // Fallback a localStorage
      const savedPoints = localStorage.getItem("imperial_points")
      const savedHistory = localStorage.getItem("imperial_points_history")
      
      if (savedPoints) setPoints(Number.parseInt(savedPoints, 10))
      if (savedHistory) setPointsHistory(JSON.parse(savedHistory))
      
      toast({
        title: "Modo offline",
        description: "Usando puntos locales",
        variant: "default",
      })
    } catch (error) {
      console.error('Error refrescando puntos:', error)
    } finally {
      setIsLoading(false)
    }
  }, [user?.id, toast])

  // Obtener puntos actuales del usuario
  const getCurrentUserPoints = useCallback(async (): Promise<number> => {
    try {
      if (!user?.id) {
        const savedPoints = localStorage.getItem("imperial_points")
        return savedPoints ? Number.parseInt(savedPoints, 10) : 250
      }

      const pb = getPbClient()
      if (pb) {
        try {
          const userRecord = await pb.collection('users').getOne(user.id)
          return userRecord.points || 250
        } catch (error) {
          console.warn('Error obteniendo puntos de PocketBase:', error)
        }
      }

      const savedPoints = localStorage.getItem("imperial_points")
      return savedPoints ? Number.parseInt(savedPoints, 10) : 250
    } catch (error) {
      console.error('Error en getCurrentUserPoints:', error)
      return 250
    }
  }, [user?.id])

  // Agregar puntos
  const addPoints = useCallback(async (amount: number, description?: string) => {
    try {
      if (amount <= 0) return

      if (!user?.id) {
        // Modo local
        const newPoints = points + amount
        setPoints(newPoints)
        localStorage.setItem("imperial_points", newPoints.toString())
        
        const newHistory = [...points_history, {
          amount,
          type: "earned" as const,
          description: description || "Puntos ganados",
          timestamp: new Date().toISOString()
        }]
        setPointsHistory(newHistory)
        localStorage.setItem("imperial_points_history", JSON.stringify(newHistory))
        return
      }

      // Intentar con PocketBase
      const pb = getPbClient()
      if (pb) {
        try {
          const userRecord = await pb.collection('users').getOne(user.id)
          const newPoints = (userRecord.points || 250) + amount
          
          await pb.collection('users').update(user.id, { points: newPoints })
          setPoints(newPoints)

          // Registrar en historial
          if (pb.authStore.token) {
            await pb.collection('points_history').create({
              user: user.id,
              amount,
              type: 'earned',
              description: description || "Puntos ganados del pedido"
            })
          }
          return
        } catch (pbError) {
          console.warn('Error con PocketBase, usando modo local:', pbError)
        }
      }

      // Fallback local
      const newPoints = points + amount
      setPoints(newPoints)
      localStorage.setItem("imperial_points", newPoints.toString())
    } catch (error) {
      console.error('Error agregando puntos:', error)
      throw error
    }
  }, [points, points_history, user?.id])

  // Usar puntos
  const usePoints = useCallback(async (amount: number, description?: string): Promise<boolean> => {
    try {
      if (amount <= 0) return true

      if (!user?.id) {
        // Modo local
        if (points >= amount) {
          const newPoints = points - amount
          setPoints(newPoints)
          localStorage.setItem("imperial_points", newPoints.toString())
          
          const newHistory = [...points_history, {
            amount,
            type: "spent" as const,
            description: description || "Puntos usados",
            timestamp: new Date().toISOString()
          }]
          setPointsHistory(newHistory)
          localStorage.setItem("imperial_points_history", JSON.stringify(newHistory))
          return true
        }
        return false
      }

      // Intentar con PocketBase
      const pb = getPbClient()
      if (pb) {
        try {
          const userRecord = await pb.collection('users').getOne(user.id)
          
          if (userRecord.points >= amount) {
            const newPoints = userRecord.points - amount
            
            await pb.collection('users').update(user.id, { points: newPoints })
            setPoints(newPoints)

            // Registrar en historial
            if (pb.authStore.token) {
              await pb.collection('points_history').create({
                user: user.id,
                amount,
                type: 'spent',
                description: description || "Puntos usados para descuento"
              })
            }
            return true
          }
          return false
        } catch (pbError) {
          console.warn('Error con PocketBase, usando modo local:', pbError)
        }
      }

      // Fallback local
      if (points >= amount) {
        const newPoints = points - amount
        setPoints(newPoints)
        localStorage.setItem("imperial_points", newPoints.toString())
        return true
      }
      return false
    } catch (error) {
      console.error('Error usando puntos:', error)
      return false
    }
  }, [points, points_history, user?.id])

  useEffect(() => {
    refreshPoints()
  }, [refreshPoints])

  const value: PointsContextType = {
    points,
    is_loading,
    addPoints,
    usePoints,
    points_history,
    refreshPoints,
    getCurrentUserPoints
  }

  return (
    <PointsContext.Provider value={value}>
      {children}
    </PointsContext.Provider>
  )
}

export function usePoints() {
  const context = useContext(PointsContext)
  if (!context) {
    throw new Error("usePoints debe usarse dentro de PointsProvider")
  }
  return context
}